/// Whether to treat an `'ambiguous'` character as wide.
///
/// The type comment says `@default true`. `index.js` defaults `ambiguousAsWide` to `false`
/// (`{ambiguousAsWide = false} = {}`). Observable behavior wins: `None` is false, applied inside
/// [`east_asian_width`].
///
/// PORT: `index.d.ts` documents `@default true`; the implementation default is `false`.
#[derive(Clone, Copy, Debug, Default)]
pub struct EastAsianWidthOptions {
    pub ambiguous_as_wide: Option<bool>,
}

